import { expect, test } from "bun:test";

import { typings, typingsPath } from "./typings.ts";

test("the typings name each class, sorted, and nothing else", () => {
  const css = `.title { color: red } .key-label:hover { color: blue } @keyframes fade { from { opacity: 0 } }`;
  expect(typings("Sheet.module.css", css)).toBe(
    [
      "// The classes of Sheet.module.css, generated by `mise run generate:css-types`. Don't edit.",
      "declare const classes: {",
      "  readonly fade: string;",
      '  readonly "key-label": string;',
      "  readonly title: string;",
      "};",
      "export default classes;",
      "",
    ].join("\n"),
  );
});

test("the typings sit next to their stylesheet", () => {
  expect(typingsPath("src/app/App.module.css")).toBe("src/app/App.module.d.css.ts");
});
